 83→export type TooltipTitleProps = React.PropsWithChildren<ComponentProps<'h1'>>;
 84→
 85→/**
 86→ * Tooltip title. Can be optionally used as tooltip children.
 87→ */
 88→export const TooltipTitle = ({ children }: TooltipTitleProps) => (
 89→  <h1 className={cl['bk-tooltip__title']}>{children}</h1>
 90→);
