 22→
 23→const getFlexValueFromColumn = <D extends object>(col: ReactTable.ColumnInstance<D>) => {
 24→  return (col?.bkColumnWidth?.flex ?? 1); // defaults to 1
 25→};
 26→
 27→const getFlexColumnWidth = <D extends object>(col: ReactTable.ColumnInstance<D>) => {
 28→  return (col?.bkColumnWidth?.width ?? 0);
 29→};
 30→
 31→const isFlexColumn = <D extends object>(col: ReactTable.ColumnInstance<D>) => {
 32→  return (col && Object.hasOwn(col, 'bkColumnWidth'));
 33→};
 34→
 35→const requireNewCol = <D extends object>(col: ReactTable.ColumnInstance<D>) => {
 36→  return (isFlexColumn(col) && (col.bkColumnWidth?.flex ?? 0) > 0);
 37→};
 38→
 39→const calculateFlexPercentage = <D extends object>(
 40→  allColumns: ReactTable.ColumnInstance<D>[],
 41→  targetColumn: ReactTable.ColumnInstance<D>
 42→) => {
 43→  if (!isFlexColumn(targetColumn)) {
 44→    return 0;    
 45→  }
 46→
 47→  const targetColumnFlex = getFlexValueFromColumn(targetColumn);
 48→  const totalFlex = allColumns.reduce((total, column) => total + getFlexValueFromColumn(column), 0);
 49→  
 50→  if (targetColumnFlex === 0) {
 51→    return 0;
 52→  }
 53→  
 54→  return totalFlex > 0 ? Math.round((targetColumnFlex / totalFlex) * 100) : 0;
 55→};
 56→
 57→export const generateCustomColGroup = <D extends object>(
 58→  allColumns: ReactTable.ColumnInstance<D>[],
 59→  columnGroups?: React.ReactNode): React.ReactNode | null => {
 60→  if (columnGroups) {
 61→    return columnGroups;
 62→  } else {
 63→    // Generate a new <colgroup>
 64→    const cols: React.ReactNode[] = [];
 65→
 66→    allColumns.forEach((col) => {
 67→      cols.push(
 68→        <col
 69→          key={`${col.id}-base`}
 70→          style={{
 71→            ...col.style,
 72→            inlineSize: isFlexColumn(col) ? getFlexColumnWidth(col) : col?.style?.width ?? '10ch'
 73→          }}
 74→        />
 75→      );
 76→      if (requireNewCol(col)) {
 77→        //Add extra dummy cols for using colspan
 78→        cols.push(
 79→          <col
 80→            key={`${col.id}-stretch`}
 81→            style={{
 82→              inlineSize: `${calculateFlexPercentage(allColumns, col)}%`
 83→            }}
 84→          />
 85→        );
 86→      }
 87→    });
 88→
 89→    return <colgroup>{cols}</colgroup>;
 90→  }
 91→};
 92→
 93→const getTotalColSpan = <D extends object>(columns: ReactTable.ColumnInstance<D>[]) => {
 94→  return columns.reduce((total, col) => total + (requireNewCol(col) ? 2 : 1), 0);
 95→};
 96→
 97→type ColumnPosition = 'first' | 'last';
 98→
 99→export const isColumnAtPosition = <D extends object>(
100→  column: ReactTable.ColumnInstance<D>,
101→  visibleColumns: ReactTable.ColumnInstance<D>[],
102→  position: ColumnPosition
103→): boolean => {
104→  if (position === 'first') {
105→    return column.id === visibleColumns[0]?.id;
106→  } else if (position === 'last') {
107→    return column.id === visibleColumns[visibleColumns.length - 1]?.id;
108→  }
109→
110→  return false;
111→};
112→
113→const isColumnSticky = <D extends object>(
114→  position: ColumnPosition,
115→  column: ReactTable.ColumnInstance<D>,
116→  table: ReactTable.TableInstance<D>,
117→) => {
118→  return isColumnAtPosition(column, table.visibleColumns, position)
119→    && !!table?.bkStickyColumns
120→    && (table?.bkStickyColumns === position || table?.bkStickyColumns === 'both')
121→};
122→
123→const getCommonClassNamesForColumn = <D extends object>(
124→  column: ReactTable.ColumnInstance<D>,
125→  table: ReactTable.TableInstance<D>,
126→) => {
127→  return ({
128→    [cl['column-sticky']]: (isColumnSticky('last', column, table)
129→      || isColumnSticky('first', column, table)),
130→    [cl['column-sticky--right']]: isColumnSticky('last', column, table),
131→    [cl['column-sticky--left']]: isColumnSticky('first', column, table),
132→  });
133→};
134→
135→// Note: `placeholder` is included in `table` props as part of "Standard HTML Attributes", but it's not actually a
136→// valid `<table>` attribute, so we can safely override it.
137→type DataTableProps<D extends object> = Omit<ComponentProps<'table'>, 'placeholder'> & {
138→  table: ReactTable.TableInstance<D>,
139→  columnGroups?: React.ReactNode,
140→  footer?: React.ReactNode,
141→  placeholder?: React.ReactNode,
142→  endOfTablePlaceholder?: React.ReactNode,
143→  children?: React.ReactNode,
144→};
145→export const DataTable = <D extends object>(props: DataTableProps<D>) => {
146→  const {
147→    table,
148→    columnGroups,
149→    footer,
150→    placeholder,
151→    endOfTablePlaceholder,
152→    children,
153→    ...propsRest
154→  } = props;
155→
156→  const scrollWrapperRef = React.useRef<HTMLDivElement>(null);
157→  const [overflowPosition, setOverflowPosition] = React.useState<'left' | 'right' | 'center' | null>(null);
158→  const scrollProps = useScroller({ scrollDirection: 'horizontal' });
159→  
160→  // biome-ignore lint/correctness/useExhaustiveDependencies: Required for column manager
161→  React.useEffect(() => {
162→    const el = scrollWrapperRef.current;
163→
164→    if (!el) return;
165→
166→    const updateOverflowPosition = () => {
167→      const { scrollLeft, scrollWidth, clientWidth } = el;
168→
169→      // If no horizontal overflow, reset position
170→      if (scrollWidth <= clientWidth) {
171→        setOverflowPosition(null);
172→        return;
173→      }
174→
175→      const atStart = scrollLeft === 0;
176→      const atEnd = Math.ceil(scrollLeft + clientWidth) >= scrollWidth;
177→
178→      let position: 'left' | 'right' | 'center';
179→      if (atStart) {
180→        position = 'left';
181→      } else if (atEnd) {
182→        position = 'right';
183→      } else {
184→        position = 'center';
185→      }
186→
187→      setOverflowPosition(position);
188→    };
189→
190→    updateOverflowPosition();
191→
192→    el.addEventListener('scroll', updateOverflowPosition);
193→    window.addEventListener('resize', updateOverflowPosition);
194→
195→    return () => {
196→      el.removeEventListener('scroll', updateOverflowPosition);
197→      window.removeEventListener('resize', updateOverflowPosition);
198→    };
199→  }, [table.visibleColumns]);
200→  
201→  const customColGroup = React.useMemo(() => generateCustomColGroup(table.visibleColumns, columnGroups),
202→    [table.visibleColumns, columnGroups]);
203→  
204→  // Currently we only support one header group
205→  const headerGroup: undefined | ReactTable.HeaderGroup<D> = table.headerGroups[0];
206→  if (!headerGroup) { return null; }
207→  
208→  const { key, ...HeaderGroupPropsRest } = headerGroup.getHeaderGroupProps();
209→  
210→  return (
211→    <>
212→      <div
213→        {...scrollProps}
214→        ref={scrollWrapperRef}
215→        className={cx(cl['bk-data-table-container'], {
216→            [cl['bk-data-table-container--scrolled-left']]: overflowPosition === 'left'
217→              || overflowPosition === 'center',
218→            [cl['bk-data-table-container--scrolled-right']]: overflowPosition === 'right'
219→              || overflowPosition === 'center',
220→          },
221→          scrollProps.className
222→        )}
223→      >
224→        <table
225→          {...table.getTableProps()}
226→          className={cx(cl['bk-data-table__table'], props.className)}
227→        >
228→          {customColGroup}
229→          
230→          <thead>
231→            <tr key={key} {...HeaderGroupPropsRest}>
232→              {/*<th/> {/ * Empty header for the selection checkbox column */}
233→              
234→              {headerGroup.headers.map((column: ReactTable.HeaderGroup<D>) => {
235→                const { key: headerKey, ...headerProps } = column.getHeaderProps([
236→                  // Note: the following are supported through custom interface merging in `src/types/react-table.d.ts`
237→                  {
238→                    className: column.className,
239→                    style: column.style,
240→                  },
241→                  column.getSortByToggleProps(),
242→                ]);
243→                
244→                const useExtraColSpan = requireNewCol(column);
245→                
246→                const getAriaSort = () => {
247→                  if (!column.canSort || !column.isSorted) { return undefined };
248→                  return column.isSortedDesc ? 'descending' : 'ascending';
249→                };
250→                
251→                const getSortIconLabel = () => {
252→                  if (!column.isSorted) {
253→                    return 'Change sort order';
254→                  };
255→                  return `Change to ${column.isSortedDesc ? 'ascending' : 'descending'} sort`;
256→                };
257→                
258→                return (
259→                  <th
260→                    aria-sort={getAriaSort()}
261→                    {...headerProps}
262→                    key={headerKey}
263→                    title={undefined} // Unset the default `title` from `getHeaderProps()`
264→                    {...useExtraColSpan ? { colSpan: 2 } : {}}
265→                    className={cx(headerProps.className, getCommonClassNamesForColumn(column, table))}
266→                  >
267→                    <div className={cx(cl['column-header'])}> {/* Wrapper element needed to serve as flex container */}
268→                      {typeof column.render('Header') === 'string'
269→                        ? <TextLine>{column.render('Header')}</TextLine>
270→                        : column.render('Header')
271→                      }
272→                      {column.canSort &&
273→                        <IconButton 
274→                          icon="caret-down"
275→                          label={getSortIconLabel()}
276→                          className={cx(
277→                            cl['sort-indicator'],
